from collections import deque
def components(g):
    seen=set(); res=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); cells=[]
                while q:
                    a,b=q.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]) and (x,y) not in seen and g[x][y]==v:
                            seen.add((x,y)); q.append((x,y))
                res.append((v,cells))
    return res
def push_right(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    objs=components(g)
    objs.sort(key=lambda o:(max(r for r,c in o[1]), max(c for r,c in o[1])), reverse=True)
    for v,cells in objs:
        best=0
        for s in range(1,w):
            if all(c+s<w and out[r][c+s]==0 for r,c in cells): best=s
            else: break
        for r,c in cells: out[r][c+best]=v
    return out
